CREATE TABLE [dbo].[ccHistorialListaNegra](	  [idhistorial] INT NOT NULL IDENTITY(1,1)	, [callout_id] INT NULL	, [telefono] VARCHAR(19) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [fecha] DATETIME NOT NULL DEFAULT(getdate())	, [cam_id] SMALLINT NULL	, [idtipomov] INT NOT NULL	, [idtipolista] INT NULL	, CONSTRAINT [PK_ccHistorialListaNegra] PRIMARY KEY ([idhistorial] ASC))ALTER TABLE [dbo].[ccHistorialListaNegra] WITH CHECK ADD CONSTRAINT [FK_ccHistorialListaNegra_ccTipoMovsListaNegra] FOREIGN KEY([idtipomov]) REFERENCES [dbo].[ccTipoMovsListaNegra] ([idtipomov])ALTER TABLE [dbo].[ccHistorialListaNegra] CHECK CONSTRAINT [FK_ccHistorialListaNegra_ccTipoMovsListaNegra]ALTER TABLE [dbo].[ccHistorialListaNegra] WITH CHECK ADD CONSTRAINT [FK_ccHistorialListaNegra_ccTiposListaNegra] FOREIGN KEY([idtipolista]) REFERENCES [dbo].[ccTiposListaNegra] ([idtipolista])ALTER TABLE [dbo].[ccHistorialListaNegra] CHECK CONSTRAINT [FK_ccHistorialListaNegra_ccTiposListaNegra]ALTER TABLE [dbo].[ccHistorialListaNegra] WITH NOCHECK ADD CONSTRAINT [FK_ccHistorialListaNegra_ccCamps] FOREIGN KEY([cam_id]) REFERENCES [dbo].[ccCamps] ([cam_id])ALTER TABLE [dbo].[ccHistorialListaNegra] CHECK CONSTRAINT [FK_ccHistorialListaNegra_ccCamps]CREATE NONCLUSTERED INDEX [IX_ccHistorialListaNegra] ON [dbo].[ccHistorialListaNegra] ([telefono] ASC)CREATE NONCLUSTERED INDEX [IX_ccHistorialListaNegra_1] ON [dbo].[ccHistorialListaNegra] ([fecha] ASC)CREATE NONCLUSTERED INDEX [IX_ccHistorialListaNegra_2] ON [dbo].[ccHistorialListaNegra] ([cam_id] ASC)CREATE NONCLUSTERED INDEX [IX_ccHistorialListaNegra_3] ON [dbo].[ccHistorialListaNegra] ([idtipomov] ASC)